package android.animation;import java.util.*;public class Animator{public interface AnimatorListener{void onAnimationStart(Animator a);void onAnimationEnd(Animator a);void onAnimationCancel(Animator a);void onAnimationRepeat(Animator a);}protected final List<AnimatorListener> listeners=new ArrayList<>();public boolean running,cancelled;public void addListener(AnimatorListener l){listeners.add(l);}public void removeAllListeners(){listeners.clear();}public void cancel(){running=false;cancelled=true;}public void start(){running=true;}}
